'use strict';
const $=s=>document.querySelector(s),key='kumfer-owner-draft-v1';
const fields=[['Company','Company name',true],['Contact','Contact name',false],['email','Email',false],['number','Phone',false],['Main Location','City or ZIP code',false],['Category','Category',true],['Specialty','Services / specialty',false],['Service_Area','Service area',false],['Testimonial','Directory note',false],['Rating','Original internal rating (1–5; not displayed)',false]];
let entries=[],editing=-1,source=[];
const esc=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const valid=data=>Array.isArray(data)&&data.every(p=>p&&typeof p.Company==='string'&&typeof p.Category==='string'&&fields.every(([f])=>p[f]===undefined||typeof p[f]==='string'||(f==='Rating'&&typeof p[f]==='number')));
function persist(){try{localStorage.setItem(key,JSON.stringify(entries));$('#status').textContent=`${entries.length} providers · Draft saved on this device. Download and commit to publish.`;}catch{$('#status').textContent='Browser storage unavailable. Download your list to keep your changes.';}render();}
function render(){const q=$('#filter').value.toLowerCase();$('#list').innerHTML=entries.map((p,i)=>({p,i})).filter(({p})=>[p.Company,p.Contact,p.Category].join(' ').toLowerCase().includes(q)).map(({p,i})=>`<div class="editor-row"><div><strong>${esc(p.Company)}</strong><small>${esc(p.Contact)} · ${esc(p.Category)}</small></div><button class="button outline" data-edit="${i}">Edit</button></div>`).join('');}
function openForm(index){editing=index;const p=index<0?{}:entries[index];$('#formTitle').textContent=index<0?'Add a connection':'Edit connection';$('#providerForm').innerHTML=fields.map(([f,label,required])=>`<label>${label}${required?' *':''}${['Specialty','Service_Area','Testimonial'].includes(f)?`<textarea name="${f}">${esc(p[f])}</textarea>`:`<input name="${f}" value="${esc(p[f])}" ${required?'required':''} type="${f==='email'?'email':f==='Rating'?'number':f==='number'?'tel':'text'}" ${f==='Rating'?'min="1" max="5"':''}>`}</label>`).join('')+`<div class="form-buttons"><button class="button primary" type="submit">Save to draft</button><button class="button outline" id="cancel" type="button">Cancel</button>${index>=0?'<button class="button danger" id="delete" type="button">Remove provider</button>':''}</div>`;$('#cancel').onclick=()=>$('#formDialog').close();if($('#delete'))$('#delete').onclick=()=>{if(confirm(`Remove ${entries[editing].Company} from this draft?`)){entries.splice(editing,1);persist();$('#formDialog').close();}};$('#formDialog').showModal();$('#providerForm input').focus();}
$('#providerForm').onsubmit=e=>{e.preventDefault();const data=new FormData(e.target),entry=editing<0?{}:{...entries[editing]};fields.forEach(([f])=>{entry[f]=f==='Rating'?Number(data.get(f))||4:String(data.get(f)||'').trim();});if(!entry.Company||!entry.Category)return;if(editing<0)entries.push(entry);else entries[editing]=entry;persist();$('#formDialog').close();};
$('#list').onclick=e=>{const b=e.target.closest('[data-edit]');if(b)openForm(Number(b.dataset.edit));};$('#add').onclick=()=>openForm(-1);$('#cancelTop').onclick=()=>$('#formDialog').close();$('#filter').oninput=render;
$('#download').onclick=()=>{const blob=new Blob([JSON.stringify(entries,null,2)+'\n'],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='providers_clean.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);$('#status').textContent='Downloaded. Replace providers_clean.json in GitHub and commit to publish.';};
$('#import').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{const next=JSON.parse(await file.text());if(!valid(next))throw Error();if(confirm(`Replace the current draft with ${next.length} imported providers?`)){entries=next;persist();}}catch{alert('This file must be a JSON list with Company and Category fields for each provider.');}e.target.value='';};
$('#restore').onclick=()=>{if(confirm('Discard your saved draft and reload the published list?')){entries=structuredClone(source);localStorage.removeItem(key);$('#status').textContent=`${entries.length} providers · Published list loaded.`;render();}};
(async()=>{try{const {data,settings:cfg}=await DirectoryData.load({requireLive:true});source=data;if(!valid(source))throw Error();entries=structuredClone(source);try{const draft=JSON.parse(localStorage.getItem(key)||'null');if(valid(draft)){entries=draft;$('#status').textContent='Your previous draft was restored. Download and commit to publish.';}else $('#status').textContent=`${entries.length} providers · Published list loaded.`;}catch{}if(/^[\w.-]+\/[\w.-]+$/.test(cfg.githubRepository||'')){$('#github').href=`https://github.com/${cfg.githubRepository}/edit/${encodeURIComponent(cfg.githubBranch||'main')}/dist/providers_clean.json`;$('#github').classList.remove('hidden');}render();}catch{$('#managerError').classList.remove('hidden');$('#add').disabled=true;$('#download').disabled=true;$('#import').disabled=true;$('#restore').disabled=true;}})();
